import{_ as t,c as s,o as l,j as e,a as n}from"./chunks/framework.Dnh4IO1K.js";const m=JSON.parse('{"title":"《周易折中》簡介","description":"周易折中 - 《周易折中》簡介","frontmatter":{"title":"《周易折中》簡介","description":"周易折中 - 《周易折中》簡介"},"headers":[],"relativePath":"classics/zhezhong/001.md","filePath":"classics/zhezhong/001.md"}'),r={name:"classics/zhezhong/001.md"};function o(c,a,i,p,d,h){return l(),s("div",null,[...a[0]||(a[0]=[e("h1",{id:"《周易折中》簡介",tabindex:"-1"},[n("《周易折中》簡介 "),e("a",{class:"header-anchor",href:"#《周易折中》簡介","aria-label":"Permalink to “《周易折中》簡介”"},"​")],-1),e("p",null,"《周易折中》是清代康熙朝大臣李光地所著的一部易學著作，也是康熙皇帝敕命主持撰寫的重要文獻。該書以通俗易懂的語言，遍採諸家大儒之說，詳加考訂，闡幽發微，是學《易》、研《易》者的案頭必備之書。",-1),e("p",null,"在內容上，《周易折中》兼講象數與義理，集漢易、宋易之大成。李光地極為推崇朱熹、程頤的註解，認為朱熹《周易本義》“獨得《易》之本義”，程氏《易傳》詮釋“《易》之義理為詳”。 （朱熹之學在歷史上有一定爭議） 因此，在解釋經文時，他首先列出《本義》，其次是《程傳》，然後再輔以“集說”、“附錄”、“總論”及“案”語等，以全面展示各家之說。此外，書中還詳細探討了先後天八卦的方位，這種探討對於易學研究具有重要的指導意義。",-1),e("p",null,"在編纂背景上，康熙皇帝深知李光地“素學有本，易理精詳”，因此選擇他作為總裁修訂此書。李光地僅用兩年時間就主持完成了《折中》的編撰工作，這體現了他的深厚學術功底和卓越貢獻。",-1),e("p",null,"從影響上來看，《周易折中》是研究清代易學最重要的典籍之一，對於後來的易學研究和經學發展具有重要的意義。它推動了中國傳統文化的發展和繁榮，使得更多的人能夠理解和掌握易學的精髓和義理。在今天的社會中，我們仍然可以從《周易折中》中汲取智慧和啟示。",-1),e("p",null,"請注意，為了方便閱讀查找，錄入內容並沒有採取原來的分卷次序，詳情可查看四庫全書。",-1),e("p",null,"總的來說，《周易折中》是一部集合多家思想、深入淺出的易學著作，對於易學研究者和愛好者來說具有重要的參考和借鑑價值。",-1)])])}const _=t(r,[["render",o]]);export{m as __pageData,_ as default};
